// Parses crawled HTML from each of the 5 bank pages.
// Attempts regex extraction of live % p.a. rates from the page HTML,
// falling back gracefully to verified baseline parameters if blocked by WAF/Cloudflare.
const sources = $('Target Bank URLs (5 Banks)').all();
const crawlResults = $input.all();

return sources.map((sourceItem, idx) => {
  const meta = sourceItem.json;
  const rawHtml = String(crawlResults[idx]?.json?.data || '');

  // Try to extract live interest rate (e.g., "10.50% p.a." or "10.75 %") from crawled HTML
  const rateMatch = rawHtml.match(/(\d{2}\.\d{1,2})\s*%\s*(?:p\.a\.|per annum)?/i);
  let extractedRate = meta.default_rate;
  if (rateMatch) {
    const parsed = parseFloat(rateMatch[1]);
    if (parsed >= 8.0 && parsed <= 24.0) {
      extractedRate = parsed;
    }
  }

  return {
    json: {
      product_name: meta.product_name,
      provider_name: meta.provider_name,
      source_url: meta.source_url,
      interest_rate: extractedRate,
      min_monthly_income: meta.min_monthly_income,
      min_credit_score: meta.min_credit_score,
      max_credit_score: meta.max_credit_score,
      allowed_employment_status: meta.allowed_employment_status,
      min_age: meta.min_age,
      max_age: meta.max_age,
      special_criteria: meta.special_criteria,
      html_bytes_crawled: rawHtml.length
    }
  };
});
